import 'package:flutter/material.dart';
class ReplyPreview extends StatelessWidget { const ReplyPreview({super.key, required this.text, this.onClose}); final String text; final VoidCallback? onClose; @override Widget build(BuildContext context) => Container(padding: const EdgeInsets.all(10), decoration: BoxDecoration(color: Theme.of(context).colorScheme.secondaryContainer, borderRadius: BorderRadius.circular(12)), child: Row(children: <Widget>[const Icon(Icons.reply), const SizedBox(width: 8), Expanded(child: Text('رد على: $text', maxLines: 1, overflow: TextOverflow.ellipsis)), if (onClose != null) IconButton(onPressed: onClose, icon: const Icon(Icons.close))])); }
